SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (414, 640, 681, 719, 776, 796, 951, 976, 979, 1030) ORDER BY g.id;
